      next = {18}
    },
    [18] = {
      beijing = 4822,
      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194107,
      role3 = 4194210,
      role5 = 4194401,
      sentence = "Of course, one keen-eyed observer started heckling in a loud voice:",
      next = {19}
    },
    [19] = {
      beijing = 4822,
      dialog = 2,
      idx = 5,
      music = "1025_2024qixi",
      renming = "Passerby",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194107,
      role3 = 4194210,
      role5 = 4194401,
      ruchang = 9,
      sentence = "You didn't lose to the champ though! You lost to the lady!",
      next = {20}
    },
    [20] = {
      beijing = 8042,
      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      sentence = "We left the archery grounds amidst an uproar of voices, not only drawing the eyes of the people, but also all the countless ghosts crowding around.",
      next = {21}
    },
    [21] = {
      beijing = 8042,
      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      sentence = "The ghosts and ghouls all gave Gavin hearty claps on the back and sang the praises of his prowess just now.",
      next = {22}
    },
    [22] = {
      beijing = 8042,
      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      sentence = "Gavin couldn't have been more vexed by it all and dragged me along, dodging left and right until we came to a secluded lotus pond where he leaped in with me in his arms.",
      next = {23}
    },
    [23] = {
      beijing = 4996,
      bganim = 0,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "The world before me flipped around, and we were back in the tranquil underworld again.",
      next = {24}
    },
    [24] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "Still curious about something, I scooted up to Gavin and asked the question that had been on my mind.",
      next = {25}
    },
    [25] = {
      beijing = 4996,
      dhead = 101,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      sentence = "Gavin, could it be that a long time ago, you were a \"martial arts master\"?",
      next = {26}
    },
    [26] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "Gavin seemed to be in a good mood and answered readily.",
      next = {27}
    },
    [27] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      ruchang = -1,
      sentence = "It's just, when I was still alive, I was a champion myself, that's all.",
      voice = 2,
      next = {28}
    },
    [28] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "I gawked at him, but his tone was as cool as ever.",
      next = {29}
    },
    [29] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "Back then, all I wanted to do was serve my kingdom and never gave any thought to relations and strings in the court. I just threw myself wholeheartedly into the business of war.",
      voice = 2,
      next = {30}
    },
    [30] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "One victorious trip home, our war boat was sabotaged and sank into the river. The war was over, but so was my life.",
      voice = 2,
      next = {31}
    },
    [31] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "As he stoically told of his own demise, the corner of his lip perked up in a hint of derision.",
      next = {32}
    },
    [32] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "Those saboteurs that perpetrated that treachery were afraid I'd come back as a vengeful wraith and haunt them, so they found a wizard to trap my soul in this land.",
      voice = 2,
      next = {33}
    },
    [33] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193110,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "My curiosity now turned to heartache in the space of these few words. All those things I said before about getting ghosts to move on now seemed so heartless in this moment.",
      next = {34}
    },
    [34] = {
      beijing = 4996,
      dhead = 101,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "...What happened then?",
      next = {35}
    },
    [35] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "What happened? I spent a few hundred years trapped.",
      voice = 2,
      next = {36}
    },
    [36] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "At the start, I thought about making them pay blood for blood when I finally got free.",
      voice = 2,
      next = {37}
    },
    [37] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193114,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "But when I really did break my chains, I realized that time had moved on, and the mortal world with it.",
      voice = 2,
      next = {38}
    },
    [38] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193114,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "I leaned on his shoulder and looked into his eyes. I felt like I could see into the depths of his soul, and it was a barren expanse.",
      next = {39}
    },
    [39] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193114,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "My enemies, the emperor, the land itself... it had all slipped away in the stream of time while I was captive in this river.",
      voice = 2,
      next = {40}
    },
    [40] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "The mud of the river was finally washed away, but I hadn't moved on. I hadn't been freed.",
      voice = 2,
      next = {41}
    },
    [41] = {
      beijing = 4996,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "Feeling an unbearable loneliness and bitterness in my heart, I gripped his hand tight.",
      next = {42}
    },
    [42] = {
      beijing = 4996,
      dhead = 105,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "So... is your wish now to reenter the mortal realm and get that freedom?",
      next = {43}
    },
    [43] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "pause",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      sentence = "No.",
      voice = 2,
      next = {44}
    },
    [44] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "56_PV_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "That's all stuff from centuries ago. Going forward, I want to settle in the underworld and govern these lesser ghosts.",
      voice = 2,
      next = {45}
    },
    [45] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "56_PV_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "As long as mortals exist, there will always be people crossing these rivers, bringing with them the troubles of the world.",
      voice = 2,
      next = {46}
    },
    [46] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "56_PV_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "With the water as my mirror, what is there that I don't know or can't see?",
      voice = 2,
      next = {47}
    },
    [47] = {
      beijing = 4996,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "56_PV_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      ruchang = 9,
      sentence = "Whether as a human or a ghost, there's no real difference.",
      voice = 2,
      next = {48}
    },
    [48] = {
      beijing = 4996,
      dialog = 3,
      music = "56_PV_Tanabata",
      renwu = "npc",
      sentence = "The tangle of emotion in my chest was instantly smoothed out by these words, transformed into a clear, calm pool.",
      next = {49}
    },
    [49] = {
      beijing = 4996,
      dhead = 107,
      dialog = 1,
      music = "56_PV_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "That's right... There really is no difference between humans and ghosts.",
      next = {50}
    },
    [50] = {
      beijing = 4996,
      dialog = 3,
      music = "56_PV_Tanabata",
      renwu = "npc",
      sentence = "That's the way I saw things when I was an exorcist, and it's the way one ought to see things now, too.",
      next = {51}
    },
    [51] = {
      beijing = 4996,
      dialog = 3,
      music = "56_PV_Tanabata",
      renwu = "npc",
      sentence = "But Gavin and the other ghosts were ultimately not the same. It was this inexplicable feeling that moved me to so much sorrow and joy.",
      next = {52}
    },
    [52] = {
      beijing = 4996,
      dialog = 3,
      music = "56_PV_Tanabata",
      renwu = "npc",
      sentence = "But I still wanted to do at least something for Gavin.",
      next = {53}
    },
    [53] = {
      beijing = 4996,
      dhead = 107,
      dialog = 1,
      music = "56_PV_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "As a thank-you for accompanying me back to the mortal realm today, I'll spend the days to come strolling around the underworld with you.",
      next = {54}
    },
    [54] = {
      beijing = 4996,
      dhead = 107,
      dialog = 1,
      music = "56_PV_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "Of course, if you want to come back to the mortal realm for another visit, I'll come with you, too.",
      next = {55}
    },
    [55] = {
      beijing = 4996,
      dhead = 101,
      dialog = 1,
      music = "56_PV_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "When we're lonely, we can seek out some fun. When we're tired, we can lounge around. We don't have to care about the state of the world or obsess over enemies domestic or abroad...",
      next = {56}
    },
    [56] = {
      beijing = 4996,
      dialog = 3,
      music = "56_PV_Tanabata",
      renwu = "npc",
      sentence = "I tilted my head up and looked sincerely at him.",
      next = {57}
    },
    [57] = {
      beijing = 4996,
      dhead = 101,
      dialog = 1,
      music = "56_PV_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "We just need to be a happy human and ghost, and just do what we want to do. How does that sound?",
      next = {58}
    },
    [58] = {
      beijing = 4996,
      dialog = 3,
