      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      roleanim = 1.1,
      sentence = "Gavin laughed and dipped his head slightly. An icy breath imprinted on my lips, bringing with it a whisper only the two of us could hear.",
