    },
    [72] = {
      beijing = 54861,
      card_cg_anim = "none",
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "I had no chance at all to reply. His dripping body enveloped me like one of those flowers on the bank wet with dew.",
