      card_cg_anim = "none",
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "The waves shuddered, emanating out in ripples. Drops of water rolled down his cheek and onto the lapels of our robes, marrying them together with moisture.",
